final class MekanismSmeltRuntime {
 static final BlockPos FURNACE=new BlockPos(672,90,512);
 static void run(GameTestHelper h)throws Exception{
  var level=h.getLevel();var server=level.getServer();h.assertTrue(MekanismSmelting.supported(),"Actual exact Mekanism10.7.19 and embedded dependencies boot");var id=UUID.nameUUIDFromBytes("PremisesThirdStudent".getBytes(java.nio.charset.StandardCharsets.UTF_8));var p=server.getPlayerList().getPlayer(id);if(p==null)p=ClaimRuntimeTests.vanillaPlayer(level,id,"ThirdStudent");server.getPlayerList().deop(p.getGameProfile());var store=CommerceService.store(server);var before=store.professions(id).track(Profession.MECHANIC);var project=ConstructionService.store(server).projects().stream().filter(q->q.blueprint().toString().equals(Profession.MECHANIC.buildingId())).findFirst().orElseThrow();h.assertTrue(store.professions(id).isActive(Profession.MECHANIC),"Actual original saved enrollment at Petra's paid premises");
  if(before.completedQuestIds().contains(MekanismSmelting.QUEST)){h.assertTrue(before.xp()==200&&before.completedQuestIds().size()==2&&CraftQuestEvidence.count(p,Profession.MECHANIC,ProfessionRank.APPRENTICE,MekanismSmelting.OUTPUT)==32&&ConstructionService.structureIntact(level,project),"Actual restart restores32native osmium evidence, earned200XP/original Petra and incomplete Apprentice band");CommerceService.verifyReceipt(p);server.tickRateManager().setTickRate(20);com.mojang.logging.LogUtils.getLogger().info("MEKANISM_SMELT_RESTART_PASSED: exact native osmium counts/canonical physical inventory receipt/two earned200XP/original paid Petra/enrollment survive restart without award replay");return;}
  h.assertTrue(before.xp()==100&&before.completedQuestIds().size()==1,"Original genuine native daily contract only");for(String recipe:MekanismSmelting.RECIPES)h.assertTrue(server.getRecipeManager().byKey(net.minecraft.resources.ResourceLocation.parse(recipe)).isPresent(),"Exact actual native registered osmium primary recipe "+recipe);level.getChunk(FURNACE);ClaimRuntimeTests.ftbUnclaim(level,FURNACE);ClaimRuntimeTests.ftbClaim(p,FURNACE);ClaimRuntimeTests.opacUnclaim(level,FURNACE);ClaimRuntimeTests.opacClaim(level,id,FURNACE);h.assertTrue(level.getBlockState(FURNACE).isAir(),"Private station never overwrites old structure");level.setBlock(FURNACE.below(),Blocks.STONE.defaultBlockState(),3);CreateDriveRuntime.place(h,p,FURNACE,new ItemStack(Items.BLAST_FURNACE),FURNACE.below(),Direction.UP);
  DimensionTravelRuntimeTests.seed(server,5);smelt(h,p,2);h.assertTrue(CraftQuestEvidence.count(p,Profession.MECHANIC,ProfessionRank.APPRENTICE,MekanismSmelting.OUTPUT)==0,"Ordinary native Tier5processing grants no Tier6profession evidence");DimensionTravelRuntimeTests.seed(server,6);CreateCraftRuntime.counter(p,project);boolean denied=false;try{ProfessionService.review(p,"materials:"+MekanismSmelting.QUEST);}catch(IllegalStateException expected){denied=true;}h.assertTrue(denied,"Real untracked osmium stock cannot replace personal native processing");smelt(h,p,32);h.assertTrue(CraftQuestEvidence.count(p,Profession.MECHANIC,ProfessionRank.APPRENTICE,MekanismSmelting.OUTPUT)==32,"Exactly32actual eligible native blast outputs, excluding old low-tier stock");
  CreateCraftRuntime.counter(p,project);var q=ProfessionService.review(p,"materials:"+MekanismSmelting.QUEST);var old=p.getInventory().getItem(8).copy();p.getInventory().setItem(8,new ItemStack(Items.DIRT));denied=false;try{ProfessionService.confirm(p,q.nonce());}catch(IllegalStateException expected){denied=true;}h.assertTrue(denied&&store.professions(id).track(Profession.MECHANIC).xp()==100,"Changed inventory refuses native delivery/XP");p.getInventory().setItem(8,old);CreateCraftRuntime.deliver(h,p,project,MekanismSmelting.QUEST);h.assertTrue(p.getInventory().countItem(CreateCraftRuntime.item(MekanismSmelting.OUTPUT))==2&&store.professions(id).track(Profession.MECHANIC).xp()==200,"Exactly32physical osmium consumed; ordinary uncredited2stock preserved/100newXPonce");h.assertTrue(EconomyStore.open(server.getWorldPath(net.minecraft.world.level.storage.LevelResource.ROOT).resolve("data")).professions(id).equals(store.professions(id)),"Canonical delivery and original records reopen exactly");com.mojang.logging.LogUtils.getLogger().info("MEKANISM_SMELT_NATIVE_PASSED: real exact Mekanism10.7.19/Generators/native registered raw-osmium primary blast recipe, actual fuel/raw-item debit/output extraction, Tier5noquest/old-stock/changed-inventory/replay refusal,32permanentDEL/200earnedXP/original Petra; private raw supplies/station/tier/native machine time only");
 }
 static void smelt(GameTestHelper h,ServerPlayer p,int quantity){var level=p.serverLevel();var furnace=(AbstractFurnaceBlockEntity)level.getBlockEntity(FURNACE);BlacksmithRepairRuntime.near(p,FURNACE);p.openMenu(furnace);var menu=p.containerMenu;h.assertTrue(menu instanceof BlastFurnaceMenu&&furnace.getItem(0).isEmpty()&&furnace.getItem(2).isEmpty(),"Real empty native furnace menu, no planted output");menu.getSlot(0).set(new ItemStack(CreateCraftRuntime.item("mekanism:raw_osmium"),quantity));menu.getSlot(1).set(new ItemStack(Items.COAL,4));for(int n=0;n<quantity*100+40;n++)AbstractFurnaceBlockEntity.serverTick(level,FURNACE,level.getBlockState(FURNACE),furnace);h.assertTrue(furnace.getItem(0).isEmpty()&&furnace.getItem(2).is(CreateCraftRuntime.item(MekanismSmelting.OUTPUT))&&furnace.getItem(2).getCount()==quantity,"Actual exact Mekanism primary recipe/fuel/input consumed for native osmium ingots");menu.quickMoveStack(p,2);p.closeContainer();}
}
